xpath.script:
(function () {
    'use strict';

    var _lastBid = null;
    var _lastTeamId = null;

    // Park the Teams row in the free middle slot (ids unchanged, so updates keep working).
    (function parkTeams() {
        var mid = document.getElementById('pjLiveBidMid');
        var sec = document.querySelector('#pjAside > .pj-aside-sec');
        if (mid && sec) mid.appendChild(sec);
    })();

    function fmtPts(n) {
        if (window.fmtUnit) {
            try { return window.fmtUnit(n); }
            catch (e) {}
        }
        try { return Number(n || 0).toLocaleString(); }
        catch (e) { return String(n || 0); }
    }
    function syncLiveBidUnit() {
        var unitEl = document.getElementById('pjLiveBidUnit');
        // Amount already includes the symbol via fmtUnit — hide the extra unit label.
        if (unitEl) {
            if (window.fmtUnit) {
                unitEl.style.display = 'none';
            } else {
                unitEl.style.display = '';
                if (window.pointUnitSymbol) unitEl.textContent = window.pointUnitSymbol();
            }
        }
    }
    // Shrink the amount until it fits inside the highlighted card (no clipping on big numbers).
    function fitAmount(el) {
        var box = el.parentNode;
        if (!box) return;
        el.style.fontSize = '';
        var cs = getComputedStyle(box);
        var avail = box.clientWidth - parseFloat(cs.paddingLeft) - parseFloat(cs.paddingRight);
        var size = parseFloat(getComputedStyle(el).fontSize);
        var guard = 40;
        while (avail > 0 && el.scrollWidth > avail && size > 24 && guard-- > 0) {
            size *= 0.94;
            el.style.fontSize = size + 'px';
        }
    }
    window.addEventListener('resize', function () {
        var el = document.getElementById('pjLiveBidVal');
        if (el && /\d/.test(el.textContent)) fitAmount(el);
    });
    function setText(id, txt) {
        var el = document.getElementById(id);
        if (el) el.textContent = txt;
    }

    function hideLiveBid() {
        var root = document.getElementById('pjLiveBid');
        if (root) {
            root.style.display = 'none';
            root.classList.remove('is-sold', 'is-waiting', 'is-unsold', 'is-updated');
        }
        _lastBid = null;
        _lastTeamId = null;
    }

    function flashIfChanged(root, bid, teamId) {
        var changed = (_lastBid !== null) && (bid !== _lastBid || teamId !== _lastTeamId);
        _lastBid = bid;
        _lastTeamId = teamId;
        if (!changed || !root) return;
        root.classList.remove('is-updated');
        void root.offsetWidth;
        root.classList.add('is-updated');
    }

    function updateLiveBid(p) {
        var root = document.getElementById('pjLiveBid');
        if (!root) return;

        if (!p) {
            hideLiveBid();
            return;
        }

        // Unsold / withdrawn: keep the panel (with Teams and Sponsors) and explain the result.
        if (p.state === 'unsold' || p.state === 'withdrawn') {
            root.style.display = 'flex';
            syncLiveBidUnit();
            root.classList.remove('is-sold', 'is-waiting', 'is-updated');
            root.classList.add('is-unsold');
            setText('pjLiveBidLabel', 'Current Bid');
            setText('pjLiveBidVal', p.state === 'unsold' ? 'UNSOLD' : 'WITHDRAWN');
            setText('pjLiveBidNote', p.state === 'unsold'
                ? 'No bids were placed. This player can be brought back to the auction later.'
                : 'This player has been withdrawn and can be brought back to the auction later.');
            _lastBid = null;
            _lastTeamId = null;
            return;
        }
        root.classList.remove('is-unsold');

        var sold = p.state === 'sold';
        var bid = sold
            ? Number(p.sold_points || p.current_bid || 0)
            : ((p.current_bid && p.current_bid > 0) ? Number(p.current_bid) : 0);
        var team = sold
            ? { id: 'sold', name: p.team_name || '', logo_url: p.team_logo_url || '' }
            : (p.current_bid_team || null);
        var teamEl = document.getElementById('pjLiveBidTeam');
        var valEl = document.getElementById('pjLiveBidVal');
        var nameEl = document.getElementById('pjLiveBidName');
        var logoEl = document.getElementById('pjLiveBidLogo');

        root.style.display = 'flex';
        syncLiveBidUnit();
        root.classList.toggle('is-sold', sold);

        // No opening bid yet: keep the panel, show a waiting line (no invented number).
        if (!sold && bid <= 0) {
            root.classList.add('is-waiting');
            setText('pjLiveBidLabel', 'Current Bid');
            setText('pjLiveBidSub', 'Highest Bidder');
            if (valEl) valEl.textContent = '\u2014';
            var waitEl = document.getElementById('pjLiveBidWaiting');
            if (waitEl) waitEl.style.display = '';
            if (teamEl) teamEl.style.display = 'none';
            _lastBid = null;
            _lastTeamId = null;
            return;
        }

        root.classList.remove('is-waiting');
        setText('pjLiveBidLabel', sold ? 'Sold For' : 'Current Bid');
        setText('pjLiveBidSub', sold ? 'Sold To' : 'Highest Bidder');
        if (valEl) { valEl.textContent = fmtPts(bid); fitAmount(valEl); }
        flashIfChanged(root, bid, team && team.id ? team.id : (sold ? 'sold' : null));

        if (team && (team.name || team.logo_url) && teamEl) {
            teamEl.style.display = 'flex';
            if (nameEl) nameEl.textContent = team.name || '';
            if (logoEl) {
                var logoSrc = team.logo_url || '';
                if (!logoSrc && sold && p.team_logo) {
                    logoSrc = 'data:image/jpeg;base64,' + p.team_logo;
                }
                if (logoSrc) {
                    if (logoEl.getAttribute('src') !== logoSrc) logoEl.src = logoSrc;
                    logoEl.style.display = '';
                } else {
                    logoEl.removeAttribute('src');
                    logoEl.style.display = 'none';
                }
            }
        } else if (teamEl) {
            teamEl.style.display = 'none';
        }
    }

    // Piggyback on the main projector poll — avoid a second /data request in production.
    window._pjOnPollResult = function (result) {
        updateLiveBid((result && result.player) || null);
    };
})();
